#!/usr/bin/env python3
"""
duo_wireless.py - the Action Replay MAX DUO's GBA as a GBA Wireless Adapter.

Experimental, and separate from the save tool (maxduo_saves.py, which it shares the USB code
with: keep both files in the same folder). Needs Reckless firmware v4.2, which runs this
project's programs from the GBA's RAM. Nothing here reads or writes either cartridge.

    python duo_wireless.py --test               does a game on a second GBA detect the adapter?
    python duo_wireless.py --trace              play an adapter with a Wonder Card distributor in
                                                range, and list what the game does
    python duo_wireless.py --trace --wonder-card FILE.wc3
                                                ... offering the card from your own .wc3 file
    python duo_wireless.py --probe              2 MHz answer-encoding probe (lab use)

See docs/WIRELESS.md and docs/DISTRIBUTOR.md.
"""
import argparse
import os
import struct
import sys
import time
import zlib

import maxduo_saves
from maxduo_saves import DuoError, MaxDuo, UsbTransport, SAFE_COMMANDS, Lab, LAB_STAGE

# ===================================================================== v4.2
# Reckless v4.2 can run a program from the GBA's RAM (command 0x23). The tool
# only runs the programs built from this repository (firmware/programs.py),
# embedded here and checked by the tests against a fresh build.
CMD_RUN, RUN_ACK = 0x23, 0x214E5552
PROG_POLL, PROG_STOP, PROG_PUT = 0x2A, 0x2B, 0x2C
SAFE_COMMANDS |= {CMD_RUN, PROG_POLL, PROG_STOP, PROG_PUT}
PROGRAMS = {
    "adapter_detect": bytes.fromhex(
        ""),
    "adapter_probe": bytes.fromhex(
        ""),
    "adapter": bytes.fromhex(
        ""),
    "adapter_lab": bytes.fromhex(
        ""),
    "ereader": bytes.fromhex(
        ""),
}


def run_program(duo, name):
    """Upload one of this repository's programs and start it. Afterwards the PC
    talks to it with program_poll() and must finish with program_stop()."""
    if not duo.can_run():
        raise DuoError("running programs needs the Reckless v4.2 firmware")
    image = PROGRAMS[name]
    Lab(duo)._upload_fast(LAB_STAGE, image)
    duo.lab_resident = False                       # the staging area now holds the program
    code, val = duo.ask(CMD_RUN)
    if (code, val) != (CMD_RUN, RUN_ACK):
        raise DuoError(f"the DUO refused the program ({code:#x} {val:#x})")


def program_poll(duo, arg=0, tries=3):
    for attempt in range(tries):                 # a busy link (or Ctrl+C) can cost one packet
        try:
            code, val = duo.ask(PROG_POLL, arg)
            break
        except KeyboardInterrupt:
            raise
        except Exception:
            if attempt == tries - 1:
                raise
            time.sleep(0.5)
            getattr(duo, "drain", lambda: 0)()  # drop a late answer, so answers stay in step
    if code != PROG_POLL:
        raise DuoError(f"the program didn't answer ({code:#x} {val:#x})")
    return val


def program_stop(duo):
    code, val = duo.ask(PROG_STOP)
    if code != PROG_STOP:
        raise DuoError(f"the program didn't stop cleanly ({code:#x} {val:#x})")
    return val


def describe_adapter_status(st):
    pairs, done, good = (st >> 16) & 0xF, st >> 20 & 1, st >> 21 & 1
    if good:
        return "the game accepted the adapter ID (0x8001) - it believes a Wireless Adapter is connected"
    if done:
        return "the exchange finished, but with an unexpected ID"
    if pairs:
        return f"exchanging the NINTENDO handshake ({pairs}/4 matched)"
    if st & 0xFFFF:
        return "the game is clocking the link, waiting for the handshake to line up"
    return "nothing from the game yet"


def adapter_test(duo, args, poll_s=0.5, after_s=5.0):
    """Detection test: the DUO's GBA answers the Wireless Adapter check of a Pokemon
    game on a second GBA. Only the detection exchange - nothing is written anywhere."""
    seconds = args.adapter_test
    print("Wireless Adapter detection test (reads and writes nothing on either cartridge)")
    print("  Connect the two GBAs with a link cable whose data lines are crossed (a GBC link")
    print("  cable, CGB-003). Then switch the second GBA on with your Pokemon game.")
    run_program(duo, "adapter_detect")
    print("  Program running on the DUO's GBA. Waiting for the game's check...")
    last_text, t0, done_at, st = None, time.time(), None, 0
    try:
        while time.time() - t0 < seconds:
            st = program_poll(duo)
            text = describe_adapter_status(st)
            if text != last_text:
                print(f"  [{time.time() - t0:5.1f} s] {text}")
                last_text = text
            if st >> 21 & 1 and done_at is None:
                done_at = time.time()
            if done_at and time.time() - done_at > after_s:
                break
            time.sleep(poll_s)
    finally:
        word = program_poll(duo, 1)
        st = program_stop(duo)
    print(f"  Transfers: {st & 0xFFFF}, last word from the game: {word:08X}")
    print("  Result: " + ("PASS - the game saw a Wireless Adapter." if st >> 21 & 1 else
                         "not detected - see the notes in docs for what to check."))
    return st


ADAPTER_COMMANDS = {
    0x10: "Hello (reset)", 0x11: "signal levels", 0x12: "version", 0x13: "status", 0x14: "slot status",
    0x15: "configuration", 0x16: "broadcast data", 0x17: "setup", 0x19: "start hosting",
    0x1A: "who has joined?", 0x1B: "stop hosting", 0x1C: "start searching", 0x1D: "search results?",
    0x1E: "stop searching", 0x1F: "connect", 0x20: "connected yet?", 0x21: "finish connecting",
    0x24: "send data", 0x25: "send data, then wait", 0x26: "receive data", 0x27: "wait",
    0x30: "disconnect", 0x32: "reconnect", 0x33: "reconnected yet?", 0x34: "finish reconnecting",
    0x35: "wait (0x35)", 0x37: "resend, then wait", 0x3D: "sleep",
}
ADAPTER_EVENTS = {
    0x01: "ID exchange completed (NINTENDO / 0x8001)",
    0x02: "the adapter's turn: told the game nothing happened",
    0x03: "the game stopped answering in the middle of a command",
    0x04: "handing the clock back to the game failed",
    0x05: "the game asked for more of an answer than the adapter sent",
    0x06: "the game never noticed the adapter was ready",
    0x07: "the game connected to the distributor",
    0x08: "the distributor received the game's name over the reliable channel",
    0x09: "the distributor told the game it may join (acknowledged)",
    0x0A: "link players exchanged (the game's trainer ID follows)",
    0x0B: "Mystery Gift server step",
    0x0C: "Mystery Gift: the game sent something unexpected",
    0x0D: "the game is ready to close the link; the distributor agreed",
}
ADAPTER_TRACE_N = 32
MG_STEPS = {0: "sent the game its first script", 1: "received the game's data", 2: "sent the next script",
            3: "sent the Wonder Card (or got 'ready to end')", 4: "sent the RAM script", 5: "got 'ready to end'"}
MG_IDENTS = {16: "client script", 17: "game data", 19: "the game's answer", 20: "ready to end", 22: "Wonder Card",
             23: "Wonder News", 25: "RAM script",
             0xFFFF: "finished"}


def lost_word(data):
    """Which word the game stopped at (adapter.c traces the phase and how many answer words were
    loaded). Answer words are numbered 1, 2, ... after the header; bit 7 of the phase marks the
    watchdog: the loaded word was never clocked at all."""
    phase, n = (data >> 8) & 0x7F, data >> 16
    if data & 0x8000:
        what = {1: "a word of its request", 2: "the answer's header"}.get(phase, f"answer word {n}" if phase == 3 else "")
        return f"{what or 'phase %d' % phase} was never clocked"
    if phase == 1:
        return "no handshake during its request"
    if phase == 2:
        return "no handshake after its command word"
    if phase == 3:
        return "the answer's header was refused" if n == 1 else f"answer word {n - 1} was refused"
    if phase == 0:
        return "the last answer word was refused"
    return f"phase {phase}"


GAME_LANGUAGES = {1: "Japanese", 2: "English", 3: "French", 4: "Italian", 5: "German", 7: "Spanish"}
GAME_VERSIONS = {1: "Sapphire", 2: "Ruby", 3: "Emerald", 4: "FireRed", 5: "LeafGreen"}


def describe_game(word0):
    """The game's language and version, from the first word of its broadcast data (0x16):
    serial (low half), then RfuGameCompatibilityData (language bits 0-3, version bits 10-13)."""
    compat = word0 >> 16
    lang, version = compat & 0xF, compat >> 10 & 0xF
    return f"{GAME_LANGUAGES.get(lang, f'language {lang}')} {GAME_VERSIONS.get(version, f'version {version}')}"


def describe_trace_entry(head, data):
    cmd, length, times = head & 0xFF, (head >> 8) & 0xFF, head >> 16
    if cmd in ADAPTER_EVENTS:
        text = ADAPTER_EVENTS[cmd]
        if cmd == 0x02:
            text += f" ({data} frames)"
        elif cmd == 0x0B:
            text += f" {data >> 16}: next, {MG_IDENTS.get(data & 0xFFFF, hex(data & 0xFFFF))}"
        elif cmd == 0x03:
            text += f" ({data & 0xFF:#x}: {lost_word(data)})"
        elif cmd in (0x04, 0x05, 0x06, 0x07, 0x08, 0x09, 0x0A, 0x0C, 0x0D):
            text += f" ({data:#x})"
    else:
        text = f"{ADAPTER_COMMANDS.get(cmd, 'unknown command')} (0x{cmd:02X})"
        if length:
            text += f" {data:08X}" + (f" +{length - 1} words" if length > 1 else "")
        if cmd == 0x16 and length:
            text += f" - {describe_game(data)}"
    return text, times


PROBE_ENCODINGS = ("one-bit lag (load W<<1, SO = top bit)", "first bit late (load W, SO = top bit)",
                   "as designed")


def probe_report(duo):
    rows = []
    for e, name in enumerate(PROBE_ENCODINGS):
        v = program_poll(duo, 6 | e << 8)
        rows.append((name, v & 0xFFFF, v >> 16, program_poll(duo, 7 | e << 8)))
    print("\n  2 MHz probe - how the game took each way of answering:")
    print(f"    {'Answer loaded as':40} {'tries':>5} {'accepted':>8} {'ack got through':>15}")
    for name, tries, acc, ack in rows:
        print(f"    {name:40} {tries:5} {acc:8} {ack:15}")
    lag, first, plain = rows
    if plain[2]:
        verdict = "the plain answer sometimes works - the link is marginal rather than consistently late"
    elif lag[2] and not first[2]:
        verdict = "consistent one-bit lag: the DUO's answers arrive exactly one clock late"
    elif first[2] and not lag[2]:
        verdict = "only the first bit is late"
    elif lag[2] and first[2]:
        verdict = "mixed - both late encodings were accepted at times"
    elif sum(r[1] for r in rows):
        verdict = "no encoding was accepted - the answers are garbled, or the game can't see the ready signal"
    else:
        verdict = "no commands arrived - try going into the game's wireless menu while this runs"
    if any(r[3] for r in rows):
        verdict += "; the SO flick got an acknowledgement through"
    print("  Verdict: " + verdict)
    return rows


LINE_US = 63.556                       # one GBA scanline


def adapter_tuning_report(duo, show=True):
    """The adapter's self-tuned 'ready' flick: per-width counts, the width it settled on, its own
    timing calibration, and the link scope (the game's SO line sampled after the first flicks)."""
    spin8, poll8 = program_poll(duo, 12), program_poll(duo, 13)
    us_spin = 8 * LINE_US / spin8 if spin8 else 0.0
    us_poll = 8 * LINE_US / poll8 if poll8 else 0.0
    rows = []
    for w in range(16):
        a, b = program_poll(duo, 9 | w << 8), program_poll(duo, 10 | w << 8)
        rows.append((w, a & 0xFFFF, a >> 16, b & 0xFFFF, b >> 16))
    state = program_poll(duo, 11)
    width, ncap = state & 0xFF, (state >> 8) & 0xFF
    scope = []
    for k in range(min(ncap, 8)):
        lo, hi, meta = (program_poll(duo, 14 | (4 * k + j) << 8) for j in range(3))
        scope.append((meta & 0xFF, (meta >> 8) & 0xFF, meta >> 16, lo | hi << 32))
    if show and any(r[1] for r in rows):
        print(f"\n  'Ready' flick tuning (one width step = about {us_spin:.2f} us; "
              f"one scope sample = about {us_poll:.2f} us):")
        print(f"    {'width':>5} {'flicks':>7} {'clocked':>8} {'accepted':>9} {'refused':>8}")
        for w, p_, c, a, r in rows:
            if p_ or c or a or r:
                print(f"    {w:5} {p_:7} {c:8} {a:9} {r:8}")
        print(f"  Settled on width {width}.")
        for fw, done, word, bits in scope:
            trace_line = "".join("-" if bits >> i & 1 else "_" for i in range(min(64, done + 1 if done != 0xFF else 40)))
            end = f"word clocked by sample {done}" if done != 0xFF else "not clocked"
            print(f"    scope, width {fw:2}, word {word:04X}....: {trace_line}  ({end})")
    return dict(rows=rows, width=width, scope=scope, us_spin=us_spin, us_poll=us_poll)


def adapter_capture_report(duo, show=True):
    """The first data commands the game sent the adapter (0x24/0x25), word for word: librfu's
    framing of what a connected game says first."""
    caps = []
    for k in range(min(program_poll(duo, 15), 4)):
        head = program_poll(duo, 16 | (32 * k + 31) << 8)
        n = min((head >> 8) & 0xFF, 6)                 # the lab build keeps 6 words of each (CAP_WORDS)
        words = [program_poll(duo, 16 | (32 * k + i) << 8) for i in range(n)]
        caps.append((head & 0xFF, (head >> 8) & 0xFF, head >> 16 & 1, words))
    if show and caps:
        print("\n  What the game sent (data commands), word by word:")
        for cmd, length, connected, words in caps:
            print(f"    0x{cmd:02X} ({length} words{', connected' if connected else ''}): "
                  + " ".join(f"{w:08X}" for w in words))
    return caps


def adapter_child_report(duo, show=True):
    """What the distributor's host side received from the connected game over librfu's NI
    channel: its serial number, game data and name (26 bytes)."""
    state = program_poll(duo, 18)
    raw = b"".join(program_poll(duo, 17 | k << 8).to_bytes(4, "little") for k in range(7))[:26]
    got = (state & 0xFFFF) == 0x0046                       # librfu's SLOT_STATE_RECV_SUCCESS
    info = dict(received=got, ni_state=state & 0xFFFF, child_frames=state >> 16 & 0xFF,
                host_frames=state >> 24, raw=raw, serial=raw[0] | raw[1] << 8)
    if show and (got or info["child_frames"]):
        print(f"\n  Host side: {info['child_frames']} frames from the game, {info['host_frames']} from the host; "
              + ("the game's name was received: serial %04X, data %s" % (info["serial"], raw.hex())
                 if got else f"name not complete yet (receiver state {state & 0xFFFF:#06x})"))
    return info


# A .wc3 file (as saved by suloku's Gen III Mystery Gift Tool and kept in Project Pokemon's
# EventsGallery): checksum (4), the Wonder Card, its metadata (0x28 + 0x28), then the RAM script
# with its checksum (4 + 1000). Japanese cards are 0xA4 bytes, the others 0x14C.
WC3_LAYOUTS = {1252: ("Japanese", 0xA4), 1420: ("English/European", 0x14C)}


def _crc16_table():
    """The game's CRC-16 (CalcCRC16WithTable): reflected polynomial 0x8408, built here rather
    than copied."""
    table = []
    for i in range(256):
        c = i
        for _ in range(8):
            c = (c >> 1) ^ 0x8408 if c & 1 else c >> 1
        table.append(c)
    return table


_CRC16 = _crc16_table()


def game_crc16(data):
    crc = 0x1121
    for b in data:
        crc = (crc >> 8) ^ _CRC16[(crc ^ b) & 0xFF]
    return ~crc & 0xFFFF


def check_wc3(data):
    """The checks the game itself would make, plus a few sanity checks. Returns a list of problems
    (empty if the file looks right)."""
    problems = []
    if len(data) not in WC3_LAYOUTS:
        return [f"a .wc3 file is {' or '.join(map(str, WC3_LAYOUTS))} bytes; this one is {len(data)}"]
    _, size = WC3_LAYOUTS[len(data)]
    card = data[4:4 + size]
    script_at = 4 + size + 0x50
    script = data[script_at + 4:script_at + 4 + 1000]
    if game_crc16(card) != int.from_bytes(data[0:2], "little"):
        problems.append("the card's checksum doesn't match its contents (the file may be damaged or edited)")
    if script[0] != 0x33:
        problems.append("the RAM script doesn't start with the game's marker (0x33), so it would be ignored")
    elif game_crc16(script) != int.from_bytes(data[script_at:script_at + 2], "little"):
        problems.append("the RAM script's checksum doesn't match its contents")
    return problems


def parse_wc3(data):
    """Returns (language, card, ram_script) from a .wc3 file's bytes, or raises ValueError."""
    if len(data) not in WC3_LAYOUTS:
        raise ValueError(f"a .wc3 file is {' or '.join(map(str, WC3_LAYOUTS))} bytes; this one is {len(data)}")
    language, size = WC3_LAYOUTS[len(data)]
    card = data[4:4 + size]
    script = data[4 + size + 0x50 + 4:4 + size + 0x50 + 4 + 1000]
    flag_id, card_type = card[0] | card[1] << 8, card[8] & 3
    if flag_id == 0 or card_type > 2:
        raise ValueError("this doesn't look like a Wonder Card (no event flag, or an unknown card type)")
    return language, card, script


# Wonder News: struct WonderNews is id (2), sendType, bgType, a title and 10 body lines. English text
# fields are 40 bytes (pokeemerald), so 444 bytes in all. Japanese fields are 18 bytes - measured on
# the Japanese Old Sea Map card, whose eight text fields are 18 bytes each - so Japanese news is
# taken to be 202 bytes (unconfirmed until a real Japanese news item arrives). A file may be the bare
# struct, or the save's form with the game's CRC-16 (as a 4-byte word) in front.
NEWS_LAYOUTS = {202: "Japanese", 444: "English/European"}


def parse_wonder_news(data):
    """Returns (language, news, problems) from a Wonder News file's bytes, or raises ValueError."""
    problems = []
    if len(data) - 4 in NEWS_LAYOUTS and len(data) not in NEWS_LAYOUTS:
        crc, data = int.from_bytes(data[:2], "little"), data[4:]
        if game_crc16(data) != crc:
            problems.append("the news's checksum doesn't match its contents (the file may be damaged or edited)")
    if len(data) not in NEWS_LAYOUTS:
        sizes = " or ".join(f"{n} (or {n + 4} with its CRC)" for n in NEWS_LAYOUTS)
        raise ValueError(f"Wonder News is {sizes} bytes; this file is {len(data)}")
    if data[0] | data[1] << 8 == 0:
        problems.append("its news ID is 0, which the game treats as no news at all")
    return NEWS_LAYOUTS[len(data)], data, problems


def load_news(duo, path):
    """Hands the distributor its Wonder News (0x2C PUT, size word with bit 16 set, then a CRC check)."""
    language, news, problems = parse_wonder_news(open(path, "rb").read())
    for problem in problems:
        print(f"  Warning about {os.path.basename(path)}: {problem}")
    blob = (len(news) | 1 << 16).to_bytes(4, "little") + news
    blob += bytes(-len(blob) % 4)
    capacity = program_poll(duo, 20)
    if len(blob) > capacity:
        raise DuoError(f"the Wonder News doesn't fit ({len(blob)} bytes, room for {capacity})")
    for i in range(0, len(blob), 4):
        code, n = duo.ask(PROG_PUT, int.from_bytes(blob[i:i + 4], "little"))
        if code != PROG_PUT or n != i // 4 + 1:
            raise DuoError(f"the program didn't take the Wonder News ({code:#x} {n})")
    if program_poll(duo, 21) != zlib.crc32(blob):
        raise DuoError("the Wonder News arrived damaged (CRC mismatch)")
    print(f"  Wonder News loaded: {os.path.basename(path)} ({language}, news ID {news[0] | news[1] << 8}, "
          f"{len(news)} bytes)")
    return language, news


def load_gift(duo, path):
    """Hands the distributor its Wonder Card and RAM script (0x2C PUT, then a CRC check)."""
    raw = open(path, "rb").read()
    language, card, script = parse_wc3(raw)
    for problem in check_wc3(raw):
        print(f"  Warning about {os.path.basename(path)}: {problem}")
    blob = len(card).to_bytes(4, "little") + card + script
    blob += bytes(-len(blob) % 4)
    capacity = program_poll(duo, 20)
    if len(blob) > capacity:
        raise DuoError(f"the Wonder Card doesn't fit ({len(blob)} bytes, room for {capacity})")
    for i in range(0, len(blob), 4):
        code, n = duo.ask(PROG_PUT, int.from_bytes(blob[i:i + 4], "little"))
        if code != PROG_PUT or n != i // 4 + 1:
            raise DuoError(f"the program didn't take the Wonder Card ({code:#x} {n})")
    if program_poll(duo, 21) != zlib.crc32(blob):
        raise DuoError("the Wonder Card arrived damaged (CRC mismatch)")
    flag_id = card[0] | card[1] << 8
    print(f"  Wonder Card loaded: {os.path.basename(path)} ({language}, event flag {flag_id:#06x}, "
          f"{len(card)} + 1000 bytes)")
    return language, card, script


LINK_STATES = ("waiting for the game", "sending player IDs", "asking for link players", "exchanging link players",
               "Mystery Gift", "done")


def adapter_link_report(duo, show=True):
    """Stage D: link_rfu_2's link players and the Mystery Gift server's progress."""
    v = program_poll(duo, 22)
    info = dict(link_state=v & 0xF, mg_step=v >> 4 & 0xF, mg_errors=v >> 8 & 0xFF, child_cmds=v >> 16,
                player=b"".join(program_poll(duo, 24 | k << 8).to_bytes(4, "little") for k in range(16))[:60],
                game_data=b"".join(program_poll(duo, 23 | k << 8).to_bytes(4, "little") for k in range(16)))
    r = program_poll(duo, 25)
    info["uni_frames"], info["resent"] = r & 0xFFFF, r >> 16
    p = info["player"]
    info["player_ok"] = p[:14] == b"GameFreak inc." and p[44:58] == b"GameFreak inc."
    info["trainer_id"] = int.from_bytes(p[20:24], "little")
    if show and info["link_state"]:
        print(f"\n  Link: {LINK_STATES[min(info['link_state'], 5)]}; {info['child_cmds']} commands from the game; "
              f"server step {info['mg_step']}" + (f", {info['mg_errors']} unexpected" if info["mg_errors"] else "")
              + (f"; {info['resent']} packets sent again" if info["resent"] else ""))
        if info["player_ok"]:
            print(f"    the game's link player: trainer ID {info['trainer_id'] & 0xFFFF:05d}, "
                  f"name bytes {p[24:32].hex()}, language {p[42]}")
        if any(info["game_data"]):
            print(f"    the game's Mystery Gift data (first 64 bytes): {info['game_data'].hex()}")
    return info


def adapter_trace(duo, args, poll_s=0.3, stop_when=None, program="adapter"):
    """The DUO's GBA plays a Wireless Adapter with nobody else in range, and lists every
    command the game sends it. Nothing is written to either cartridge."""
    seconds = args.adapter_trace if program in ("adapter", "adapter_lab") else args.adapter_probe
    if program == "adapter_probe":
        print("Wireless Adapter 2 MHz probe (reads and writes nothing on either cartridge)")
        print("  Each time the game sends a command, the DUO answers it a different way; the")
        print("  table at the end shows which ways the game accepted.")
    else:
        print("Wireless Adapter trace (reads and writes nothing on either cartridge)")
        print("  The DUO's GBA is now a Wireless Adapter, with one Wonder Card distributor in range.")
    print("  Use the game's wireless features (e.g. Mystery Gift > Wireless Communication);")
    print("  every command it sends the adapter is listed here.")
    run_program(duo, program)
    if program in ("adapter", "adapter_lab") and getattr(args, "serial", None):
        program_poll(duo, 27 | args.serial << 8)
        print(f"  Distributor serial fixed at {args.serial:#06x} (--serial).")
    if program in ("adapter", "adapter_lab") and getattr(args, "check_search", False):
        program_poll(duo, 26 | 4 << 8)
        print("  Search check: the distributor appears four times in each answer. If our answers arrive")
        print("  intact, the game stops and restarts its search every time (0x1E then 0x1C).")
    sweeping = program in ("adapter", "adapter_lab") and getattr(args, "sweep_serial", False)
    if sweeping:
        program_poll(duo, 26 | 0x10 << 8)
        print("  Serial sweep: the distributor offers every serial number in turn (about 6 minutes for")
        print("  all of them). When the game accepts one it connects, and the serial is reported here.")
    last_progress = [0.0, 0]
    card_language = None
    if program == "adapter" and getattr(args, "wonder_news", None):
        try:
            card_language = load_news(duo, args.wonder_news)[0]
        except (OSError, ValueError, DuoError) as e:
            print(f"  Wonder News not loaded ({e}); the distributor will say it has nothing to send")
    elif program in ("adapter", "adapter_lab") and getattr(args, "wonder_card", None):
        try:
            card_language = load_gift(duo, args.wonder_card)[0]
        except (OSError, ValueError, DuoError) as e:
            print(f"  Wonder Card not loaded ({e}); the distributor will say it has nothing to send")
    probe_rows = None
    entries, seen, t0 = [], 0, time.time()

    def finish_last():
        if seen:
            i = seen - 1
            head = program_poll(duo, 3 | (i % ADAPTER_TRACE_N) << 8)
            text, times = describe_trace_entry(head, entries[-1][2])
            entries[-1] = (entries[-1][0], head, entries[-1][2])
            if times > 1:
                print(f"           ... repeated, {times} times in all")
    try:
      try:
        while time.time() - t0 < seconds:
            n = program_poll(duo, 2)
            if n > seen:
                finish_last()
                if n - seen > ADAPTER_TRACE_N:
                    print(f"  ({n - seen - ADAPTER_TRACE_N} entries came too fast to show)")
                    seen = n - ADAPTER_TRACE_N
                for i in range(seen, n):
                    head = program_poll(duo, 3 | (i % ADAPTER_TRACE_N) << 8)
                    data = program_poll(duo, 4 | (i % ADAPTER_TRACE_N) << 8)
                    entries.append((time.time() - t0, head, data))
                    text, times = describe_trace_entry(head, data)
                    more = f"  (x{times} so far)" if times > 1 else ""
                    print(f"  [{time.time() - t0:6.1f} s] {text}{more}")
                    if (head & 0xFF) == 0x16 and card_language and \
                            ((data >> 16 & 0xF) == 1) != (card_language == "Japanese"):
                        print(f"  *** Warning: the {'Wonder News' if getattr(args, 'wonder_news', None) else 'Wonder Card'} "
                              f"is {card_language}, but the game is "
                              f"{describe_game(data)} - its text and script are for another language. ***")
                        card_language = None
                    seen = i + 1
            if sweeping and time.time() - last_progress[0] > 15:
                v = program_poll(duo, 26)
                last_progress[0] = time.time()
                if v >> 16 and not last_progress[1]:
                    last_progress[1] = v >> 16
                    print(f"  *** The game connected to serial {v >> 16:#06x}: that is its distributor serial. ***")
                elif not v >> 16:
                    print(f"  (sweep: now offering serials {v & 0xFFFF:#06x} to {(v & 0xFFFF) + 511:#06x})")
            if stop_when and stop_when() and program_poll(duo, 2) == seen:
                break
            time.sleep(poll_s)
      except KeyboardInterrupt:
        print("  Stopping (Ctrl+C)...")
    finally:
        counters = program_poll(duo, 5)
        if seen:
            finish_last()
        if program == "adapter_probe":
            probe_rows = probe_report(duo)
        else:
            extra = program_poll(duo, 8)
            if extra & 0xFFFF or extra >> 16:
                print(f"  Over-long answers asked for: {extra & 0xFFFF}, ready signals missed: {extra >> 16}")
            if program == "adapter_lab":                 # the lab build's instruments
                adapter_trace.last_tuning = adapter_tuning_report(duo)
                adapter_trace.last_capture = adapter_capture_report(duo)
            else:
                adapter_trace.last_tuning = adapter_trace.last_capture = None
            adapter_trace.last_child = adapter_child_report(duo)
            adapter_trace.last_link = adapter_link_report(duo)
        if program == "adapter" and getattr(args, "wonder_news", None):
            r = program_poll(duo, 28)
            adapter_trace.last_news = r
            if r >> 9 & 1 and adapter_trace.last_link and adapter_trace.last_link.get("mg_step", 0) >= 6:
                print("  Wonder News: " + ("the game already had this news, so it kept its own."
                                          if r & 0xFF else "the game saved the news."))
        if program in ("adapter", "adapter_lab"):
            v = program_poll(duo, 27)
            adapter_trace.last_serial = v
            if v >> 16:
                print(f"  Distributor serial used: {v & 0xFFFF:#06x}, for {describe_game(v)}")
        if sweeping:
            v = program_poll(duo, 26)
            print(f"  Serial sweep: " + (f"the game connected to serial {v >> 16:#06x}." if v >> 16 else
                  f"no serial accepted yet (reached {v & 0xFFFF:#06x})."))
            adapter_trace.last_sweep = v
        st = program_stop(duo)
    print(f"  Commands answered: {st >> 16}, ID exchanges: {counters & 0xFFFF}, "
          f"interrupted commands: {counters >> 16}")
    if probe_rows is not None:
        return entries, st, counters, probe_rows
    return entries, st, counters


SERIAL_PATTERNS = (0x00007F7D,        # 0x7F7D as a code constant (Rfu_GetWonderDistributorPlayerData)
                   0x7F7D0002,        # sAcceptedSerialNos = {0x0002, 0x7F7D, 0x0000, 0xFFFF}, 4-byte aligned
                   0x99660000)        # librfu's STWI header constant: shows the search ran over the code


def find_serial(duo):
    """Read-only: search the cartridge in the DUO for the Wonder Card distributor's serial number
    (0x7F7D in the English decomp) and report where it appears."""
    M = maxduo_saves
    lab = Lab(duo)
    wake = [("w16", M.MAP_REG, 0x0101), ("delay", 0, 0x400), ("r16", 0x08000000, 2)]
    res = lab.run(wake + [("r8", 0x080000A0, 16)] + M.rom_size_ops() + [("w16", M.MAP_REG, 0x0120)])
    header = res[1][1]                              # (results: only the reads, in order)
    size = M.rom_size_from([d for _, d in res[2:]])
    title = header[:12].split(b"\0")[0].decode("ascii", "replace")
    print(f"  Cartridge: {title} ({header[12:16].decode('ascii', 'replace')}), {size >> 20} MB")
    found = lab.run(wake + [("search", 0x08000000, min(size, M.MAX_ROM_READ), SERIAL_PATTERNS),
                            ("w16", M.MAP_REG, 0x0120)])[1][1]
    hits = []
    for i in range(0, 64, 16):
        addr, w0, w1, w2 = struct.unpack_from("<4I", found, i)
        if addr != 0xFFFFFFFF:
            hits.append((addr, w0, w1, w2))
            print(f"    {addr:08X}: {w0:08X} {w1:08X} {w2:08X}")
    serial = [h for h in hits if h[1] in (0x00007F7D, 0x7F7D0002)]
    if serial:
        print("  0x7F7D is in this game: it uses the same distributor serial as the English decomp.")
    elif hits:
        print("  0x7F7D was NOT found (the search did reach librfu's code): this game's distributor serial differs.")
    else:
        print("  Nothing found at all - the search may not have covered the game's code.")
    return hits


def serial_candidates(rom, base=0x08000000):
    """Look in a ROM image (in memory only) for librfu's accepted-serials list: u16s {0x0002, X,
    [0x0000,] 0xFFFF} (link_rfu_2.c: sAcceptedSerialNos). Each candidate is scored by whether code
    points at it (a literal-pool word holding its address) and whether X itself appears as a code
    constant (Rfu_GetWonderDistributorPlayerData compares against it)."""
    import array
    lists = []
    i = rom.find(b"\x02\x00")
    while 0 <= i <= len(rom) - 8:
        if not i & 1:
            x, a, b = struct.unpack_from("<3H", rom, i + 2)
            if 3 <= x <= 0x7FFF and (a == 0xFFFF or (a == 0 and b == 0xFFFF)):
                lists.append((x, base + i))
        i = rom.find(b"\x02\x00", i + 1)
    targets = {addr for _, addr in lists} | {x for x, _ in lists}
    words = array.array("I", bytes(rom[:len(rom) & ~3]))     # every aligned word, for the cross-checks
    if sys.byteorder != "little":
        words.byteswap()
    present = {w for w in words if w in targets}
    found = []
    for x, addr in lists:
        pointed, constant = addr in present, x in present
        if pointed or constant:
            found.append((pointed + constant, x, addr, pointed, constant))
    found.sort(key=lambda f: (-f[0], f[2]))
    return found


def find_serial_deep(duo, chunk=0x1FFF0):
    """Read-only: read the cartridge in the DUO into memory (never to disk) and look for the
    accepted-serials list and the distributor constant. Prints only what it finds."""
    M = maxduo_saves
    lab = Lab(duo)
    wake = [("w16", M.MAP_REG, 0x0101), ("delay", 0, 0x400), ("r16", 0x08000000, 2)]
    res = lab.run(wake + [("r8", 0x080000A0, 16)] + M.rom_size_ops() + [("w16", M.MAP_REG, 0x0120)])
    header, size = res[1][1], M.rom_size_from([d for _, d in res[2:]])
    size = min(size, M.MAX_ROM_READ)
    title = header[:12].split(b"\0")[0].decode("ascii", "replace")
    print(f"  Cartridge: {title} ({header[12:16].decode('ascii', 'replace')}), "
          f"reading {size >> 20} MB into memory (read-only)...")
    rom, t0 = bytearray(), time.time()
    for at in range(0, size, chunk):
        n = min(chunk, size - at)
        rom += lab.run(wake + [("r8", 0x08000000 + at, n), ("w16", M.MAP_REG, 0x0120)])[1][1]
        done = len(rom) / size
        print(f"\r    {done:4.0%}  ({time.time() - t0:.0f} s)", end="", flush=True)
    print()
    found = serial_candidates(bytes(rom))
    del rom
    if not found:
        print("  No accepted-serials list found.")
        return []
    print("  Candidates for the distributor serial (best first):")
    for score, x, addr, pointed, constant in found[:6]:
        why = " and ".join(w for w, f in (("code points at the list", pointed),
                                          (f"{x:#06x} is a code constant", constant)) if f)
        print(f"    serial {x:#06x}  (list at {addr:08X}: {why})")
    best = found[0]
    if best[0] == 2:
        print(f"  Most likely: {best[1]:#06x}.")
    return found


EREADER_STATES = ("waiting for the game", "handshaking", "link up", "got the game's link player",
                  "sent our link player", "sent the Mystery Event", "the game closed the link")


def load_event(duo, path):
    """Hands the e-Reader program a Mystery Event script (0x2C PUT, then a CRC check)."""
    data = open(path, "rb").read()
    if not 1 <= len(data) <= 2004:
        raise ValueError(f"a Mystery Event script is 1 to 2004 bytes (the game's buffer); this one is {len(data)}")
    blob = len(data).to_bytes(4, "little") + data
    blob += bytes(-len(blob) % 4)
    capacity = program_poll(duo, 20)
    if len(blob) > capacity:
        raise DuoError(f"the Mystery Event doesn't fit ({len(blob)} bytes, room for {capacity})")
    for i in range(0, len(blob), 4):
        code, n = duo.ask(PROG_PUT, int.from_bytes(blob[i:i + 4], "little"))
        if code != PROG_PUT or n != i // 4 + 1:
            raise DuoError(f"the program didn't take the Mystery Event ({code:#x} {n})")
    if program_poll(duo, 21) != zlib.crc32(blob):
        raise DuoError("the Mystery Event arrived damaged (CRC mismatch)")
    print(f"  Mystery Event loaded: {os.path.basename(path)} ({len(data)} bytes)")
    return data


def ereader_session(duo, args, poll_s=0.3, stop_when=None):
    """The DUO's GBA plays the Card e-Reader+ on the GBA link cable (docs/EREADER.md): it answers
    a Ruby/Sapphire (or Japanese Emerald) in its Mystery Event menu, and sends the event script.
    Nothing is written to either cartridge; the game saves the event itself."""
    seconds = getattr(args, "ereader", 600) or 600
    print("e-Reader on the link cable (reads and writes nothing on either cartridge)")
    print("  Connect a GBA link cable (AGB-005), then choose MYSTERY EVENT on the game and press A")
    print("  when it says it's ready.")
    run_program(duo, "ereader")
    event = None
    if getattr(args, "mystery_event", None):
        try:
            event = load_event(duo, args.mystery_event)
        except (OSError, ValueError, DuoError) as e:
            print(f"  Mystery Event not loaded ({e}); only link players will be exchanged (a dry run)")
    last, t0, report = None, time.time(), {}
    try:
        while time.time() - t0 < seconds:
            st = program_poll(duo, 0)
            state, master = st & 0xF, st >> 4 & 1
            if last is None or state > last:
                # print every stage passed since the last poll, so the story is complete
                for s_ in range(0 if last is None else last + 1, state + 1):
                    if last is None and s_ < state and s_ < 2:
                        continue
                    text = EREADER_STATES[s_] if s_ < len(EREADER_STATES) else f"state {s_}"
                    if s_ == 2:
                        text += f" (the DUO is player {0 if master else 1})"
                    if s_ == 3:
                        v = program_poll(duo, 2)
                        lang = GAME_LANGUAGES.get(v >> 16, f"language {v >> 16}")
                        text += f": link type {v & 0xFFFF:#06x}, {lang}"
                        report["game_link_type"], report["game_language"] = v & 0xFFFF, v >> 16
                    print(f"  [{time.time() - t0:6.1f} s] {text}")
                last = state
            if stop_when and stop_when():
                break
            time.sleep(poll_s)
    except KeyboardInterrupt:
        print("  Stopping (Ctrl+C)...")
    finally:
        extra = program_poll(duo, 1)
        st = program_stop(duo)
    report.update(state=st & 0xFF, transfers=st >> 8, bad_checksums=extra & 0xFFFF, event=event)
    print(f"  Transfers: {st >> 8}, checksum mismatches: {extra & 0xFFFF}")
    ereader_session.last = report
    return report


def run(duo, args):
    version = duo.connect(wait_s=args.wait)
    print(f"Connected to Action Replay MAX DUO (Datel protocol {version >> 8}.{version & 0xFF:02d}"
          + (", Reckless v4.2)" if duo.can_run() else ")"))
    if args.find_serial:
        return find_serial_deep(duo) if args.deep else find_serial(duo)
    if args.mystery_event or args.ereader:
        return ereader_session(duo, args)
    if args.test:
        return adapter_test(duo, argparse.Namespace(adapter_test=args.test))
    if args.probe:
        return adapter_trace(duo, argparse.Namespace(adapter_probe=args.probe), program="adapter_probe")
    return adapter_trace(duo, argparse.Namespace(adapter_trace=args.trace or 600, wonder_card=args.wonder_card,
                                                 check_search=args.check_search,
                                                 sweep_serial=args.sweep_serial, serial=args.serial,
                                                 wonder_news=args.wonder_news),
                         program="adapter_lab" if args.lab else "adapter")


def main():
    ap = argparse.ArgumentParser(description="The DUO's GBA as a GBA Wireless Adapter (experimental, firmware v4.2; "
                                             "reads and writes nothing on either cartridge)")
    ap.add_argument("--test", type=int, nargs="?", const=180, metavar="SECONDS",
                    help="answer a Pokemon game's adapter check on a second GBA (detection only; default 180 s)")
    ap.add_argument("--trace", type=int, nargs="?", const=600, metavar="SECONDS",
                    help="play a whole adapter, with a Wonder Card distributor in range, and list every command "
                         "the game sends (default 600 s; Ctrl+C stops it and prints the report)")
    ap.add_argument("--wonder-card", metavar="FILE.wc3",
                    help="with --trace: the Wonder Card the distributor offers (your own .wc3 file); without it, "
                         "the distributor says it has nothing to send")
    ap.add_argument("--check-search", action="store_true",
                    help="with --trace: list the distributor four times in each search answer; the game "
                         "restarts its search at once if the answers arrive intact (a test, not a gift)")
    ap.add_argument("--sweep-serial", action="store_true",
                    help="with --trace: offer every distributor serial number in turn until the game connects "
                         "to one (about 6 minutes; a test, not a gift)")
    ap.add_argument("--find-serial", action="store_true",
                    help="read-only: search the cartridge in the DUO for the Wonder Card distributor's serial number")
    ap.add_argument("--deep", action="store_true",
                    help="with --find-serial: read the cartridge into memory (not to disk) and find the "
                         "accepted-serials list itself (a few minutes)")
    ap.add_argument("--mystery-event", metavar="FILE",
                    help="play the Card e-Reader+ on a GBA link cable and send this Mystery Event script to "
                         "Ruby/Sapphire (or Japanese Emerald) in its MYSTERY EVENT menu (your own file)")
    ap.add_argument("--ereader", type=int, nargs="?", const=600, metavar="SECONDS",
                    help="the e-Reader with no event: link players only, a dry run")
    ap.add_argument("--wonder-news", metavar="FILE",
                    help="with --trace: the distributor offers this Wonder News instead of a card (your own file: "
                         "the bare news, or the save's form with its CRC in front)")
    ap.add_argument("--serial", type=lambda x: int(x, 16) & 0x7FFF, metavar="HEX",
                    help="with --trace: use this distributor serial instead of choosing one for the game "
                         "(Japanese Emerald 7F7F, others 7F7D until confirmed)")
    ap.add_argument("--lab", action="store_true",
                    help="with --trace: run the lab build, which also reports flick tuning, a link-port scope "
                         "and the game's first data commands")
    ap.add_argument("--probe", type=int, nargs="?", const=600, metavar="SECONDS",
                    help="lab: like --trace, but answers each command a different way to see how 2 MHz answers "
                         "reach the game")
    ap.add_argument("--wait", type=int, default=120, help="seconds to wait for the GBA to be switched on (default 120)")
    args = ap.parse_args()
    if args.wonder_news and args.wonder_card:
        ap.error("choose --wonder-card or --wonder-news, not both: the game takes one at a time")
    if args.wonder_news and args.lab:
        ap.error("the lab build sends Wonder Cards only; leave out --lab to send Wonder News")
    if not (args.test or args.trace or args.probe or args.find_serial or args.mystery_event or args.ereader):
        args.trace = 600
    t = UsbTransport()
    try:
        run(MaxDuo(t), args)
    except DuoError as err:
        sys.exit(f"\nStopped: {err}")
    except Exception as err:
        if type(err).__name__ in ("USBTimeoutError", "USBError"):
            sys.exit(f"\nThe Action Replay stopped answering ({err}).\n"
                     "Check the console batteries and that USB SERVER MODE is still showing.")
        raise
    finally:
        t.close()


if __name__ == "__main__":
    main()
